  return <><PageHeader eyebrow="STOCK ACCURACY" title="Cycle counts" description="Compare shelf quantities with your records and reconcile differences." actions={<Btn icon={Plus} onClick={()=>openModal({type:'cycleCount',title:'Open a cycle count'})}>Start a count</Btn>}/><div className="page-stats"><MiniStat label="Open counts" value={open} color="amber"/><MiniStat label="Reconciled" value={reconciled} color="green"/><MiniStat label="Variances found" value={variances}/></div><div className="panel data-panel"><div className="table-wrap"><table><thead><tr><th>Count reference</th><th>Product</th><th>Bin</th><th>Expected</th><th>Physical count</th><th>Variance</th><th>Status</th><th>Action</th></tr></thead><tbody>{rows.map(row=><tr key={row._id}><td className="mono">{row.reference}</td><td><b>{row.product?.name||'—'}</b><small className="cell-sub mono">{row.product?.code}</small></td><td><span className="location-chip">{row.bin?.code||'—'}</span></td><td>{num(row.expected)}</td><td>{row.status==='Open'?<input className="inline-count-input" aria-label={`Physical count for ${row.reference}`} type="number" min="0" step="1" value={counts[row._id]??''} onChange={e=>setCounts({...counts,[row._id]:e.target.value})} placeholder="Count units"/>:num(row.counted)}</td><td>{row.status==='Reconciled'?<b className={row.variance===0?'text-green':row.variance>0?'text-blue':'text-amber'}>{row.variance>0?'+':''}{num(row.variance)}</b>:'—'}</td><td><Status value={row.status}/></td><td>{row.status==='Open'?<button className="btn btn-primary btn-sm" disabled={counts[row._id]===undefined||counts[row._id]===''} onClick={()=>onReconcile(row._id,Number(counts[row._id]))}>Reconcile</button>:'—'}</td></tr>)}{!rows.length&&<tr><td colSpan="8"><EmptyRows text="No cycle counts yet" hint="Start a count to verify stock in any active bin."/></td></tr>}</tbody></table></div></div></>;
