function ActivityView({rows}){return <><PageHeader eyebrow="WORKSPACE HISTORY" title="Activity log" description="A searchable record of warehouse changes and movements." actions={<button className="btn btn-secondary" onClick={()=>downloadCsv('stockroom-activity.csv',rows,[['createdAt','Date'],['user.name','Team member'],['module','Module'],['action','Action'],['description','Details']])}><Download size={16}/> Export CSV</button>}/><div className="page-stats"><MiniStat label="Recorded events" value={rows.length}/><MiniStat label="Modules active" value={new Set(rows.map(x=>x.module).filter(Boolean)).size}/><MiniStat label="Latest activity" value={rows[0]?fmt(rows[0].createdAt):'—'}/></div><div className="panel data-panel"><div className="table-wrap"><table><thead><tr><th>Date</th><th>Team member</th><th>Module</th><th>Action</th><th>Details</th></tr></thead><tbody>{rows.map(row=><tr key={row._id}><td>{fmt(row.createdAt)}</td><td>{row.user?.name||'System'}</td><td>{row.module||'Workspace'}</td><td><b>{row.action||'Updated record'}</b></td><td>{row.description||'—'}</td></tr>)}{!rows.length&&<tr><td colSpan="5"><EmptyRows text="No activity recorded yet" hint="Receiving, picking and dispatch updates will appear here."/></td></tr>}</tbody></table></div></div></>}

function ReportsView({data}){
  const [tab,setTab]=useState('inventory'),[showFilters,setShowFilters]=useState(false),[from,setFrom]=useState(''),[to,setTo]=useState('');
  const labels={inventory:'Inventory',stockHealth:'Stock health',capacity:'Bin capacity',receiving:'Receiving',suppliers:'Suppliers',picking:'Picking',dispatch:'Dispatch',cycleCounts:'Cycle counts',movements:'Movements'};
  const dateField={inventory:'createdAt',stockHealth:'createdAt',capacity:'createdAt',receiving:'receivedAt',picking:'requestedAt',dispatch:'dispatchedAt',cycleCounts:'createdAt'};
  const inRange=(row,key)=>{const value=row[dateField[key]];if(!value)return !from&&!to;const date=new Date(value).toISOString().slice(0,10);return (!from||date>=from)&&(!to||date<=to)};
  const inventory=(data.inventory||[]).filter(row=>inRange(row,'inventory'));
  const receiving=(data.receiving||[]).filter(row=>inRange(row,'receiving'));
  const picking=(data.picking||[]).filter(row=>inRange(row,'picking'));
  const dispatch=(data.dispatch||[]).filter(row=>inRange(row,'dispatch'));
  const cycleCounts=(data.cycleCounts||[]).filter(row=>inRange(row,'cycleCounts'));
  const stockHealth=(data.products||[]).filter(row=>inRange(row,'stockHealth')).map(product=>{const quantity=inventory.filter(row=>row.product?._id===product._id).reduce((sum,row)=>sum+row.quantity,0);return {...product,quantity,health:quantity<=product.reorderLevel?'Low stock':'Healthy'}}).sort((a,b)=>Number(b.health==='Low stock')-Number(a.health==='Low stock'));
  const capacity=(data.bins||[]).filter(row=>inRange(row,'capacity')).map(bin=>{const used=inventory.filter(row=>row.bin?._id===bin._id).reduce((sum,row)=>sum+row.quantity,0);return {...bin,used,utilization:bin.capacity?Math.min(100,Math.round(used/bin.capacity*100)):null}});
  const supplierMap=new Map();receiving.forEach(row=>{const supplier=supplierMap.get(row.supplier)||{name:row.supplier,deliveries:0,units:0,lastReceived:row.receivedAt};supplier.deliveries++;supplier.units+=row.quantity;if(new Date(row.receivedAt)>new Date(supplier.lastReceived))supplier.lastReceived=row.receivedAt;supplierMap.set(row.supplier,supplier)});
  const suppliers=[...supplierMap.values()].sort((a,b)=>b.units-a.units);
  const movements=[...receiving.map(row=>({_id:`in-${row._id}`,date:row.receivedAt,direction:'Inbound',reference:row.reference,product:row.product,party:row.supplier,quantity:row.quantity})),...dispatch.filter(row=>row.status==='Dispatched').map(row=>({_id:`out-${row._id}`,date:row.dispatchedAt,direction:'Outbound',reference:row.orderNumber,product:row.product,party:row.customer,quantity:row.quantity}))].sort((a,b)=>new Date(b.date)-new Date(a.date));
  const reports={inventory,stockHealth,capacity,receiving,suppliers,picking,dispatch,cycleCounts,movements};
  const rows=reports[tab]||[];
  return <><PageHeader eyebrow="INSIGHTS & REPORTS" title="Reports" description="A clear view of stock and warehouse activity across your operation." actions={<button className="btn btn-secondary" onClick={()=>window.print()}><Download size={16}/> Export / print</button>}/>
    <div className="report-summary"><div><div className="report-spark"><BarChart3 size={18}/></div><small>RECORDS IN VIEW</small><b>{num(rows.length)}</b><span>{labels[tab]} report</span></div><div><div className="report-spark green"><ArrowDownRight size={18}/></div><small>INBOUND UNITS</small><b>{num(receiving.reduce((n,x)=>n+x.quantity,0))}</b><span>For selected date range</span></div><div><div className="report-spark blue"><Truck size={18}/></div><small>COMPLETED ORDERS</small><b>{num(dispatch.filter(x=>x.status==='Dispatched').length)}</b><span>For selected date range</span></div></div>
    <div className="panel data-panel"><div className="report-tabs">{Object.entries(labels).map(([key,label])=><button className={tab===key?'active':''} key={key} onClick={()=>setTab(key)}>{label} <span>{reports[key]?.length||0}</span></button>)}<button className={`report-filter ${showFilters?'active':''}`} onClick={()=>setShowFilters(!showFilters)}><SlidersHorizontal size={15}/> Filters</button></div>
    {showFilters&&<div className="report-filter-row"><label>From<input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>To<input type="date" value={to} min={from||undefined} onChange={e=>setTo(e.target.value)}/></label><button className="btn btn-secondary" onClick={()=>{setFrom('');setTo('')}}>Clear dates</button></div>}
    <div className="table-wrap"><table><thead><tr>{tab==='inventory'?<><th>Product</th><th>Bin</th><th>Warehouse</th><th>Quantity</th><th>Expiry</th></>:tab==='stockHealth'?<><th>Product</th><th>SKU</th><th>Category</th><th>On hand</th><th>Reorder level</th><th>Status</th></>:tab==='capacity'?<><th>Warehouse</th><th>Bin</th><th>Units stored</th><th>Capacity</th><th>Utilization</th></>:tab==='receiving'?<><th>Receipt</th><th>Product</th><th>Supplier</th><th>Quantity</th><th>Date</th></>:tab==='suppliers'?<><th>Supplier</th><th>Deliveries</th><th>Units received</th><th>Last received</th></>:tab==='picking'?<><th>Task</th><th>Product</th><th>Bin</th><th>Priority</th><th>Status</th></>:tab==='cycleCounts'?<><th>Count</th><th>Product</th><th>Bin</th><th>Expected</th><th>Counted</th><th>Variance</th><th>Status</th></>:tab==='dispatch'?<><th>Order</th><th>Customer</th><th>Product</th><th>Quantity</th><th>Status</th></>:<><th>Date</th><th>Direction</th><th>Reference</th><th>Product</th><th>Customer / supplier</th><th>Units</th></>}</tr></thead><tbody>{rows.slice(0,500).map(r=><tr key={r._id}>{tab==='inventory'?<><td>{r.product?.name}</td><td>{r.bin?.code}</td><td>{r.bin?.warehouse?.name}</td><td className="strong-cell">{num(r.quantity)}</td><td>{fmt(r.expiryDate)}</td></>:tab==='stockHealth'?<><td>{r.name}</td><td className="mono">{r.code}</td><td>{r.category}</td><td className="strong-cell">{num(r.quantity)}</td><td>{num(r.reorderLevel)}</td><td><span className={`status-pill ${r.health==='Healthy'?'status-completed':'status-warning'}`}>{r.health}</span></td></>:tab==='capacity'?<><td>{r.warehouse?.name||'—'}</td><td><span className="location-chip">{r.code}</span></td><td>{num(r.used)}</td><td>{r.capacity?num(r.capacity):'—'}</td><td>{r.utilization===null?'—':<><b>{r.utilization}%</b><div className="capacity-meter"><i style={{width:`${r.utilization}%`}}/></div></>}</td></>:tab==='receiving'?<><td className="mono">{r.reference}</td><td>{r.product?.name}</td><td>{r.supplier}</td><td>+{num(r.quantity)}</td><td>{fmt(r.receivedAt)}</td></>:tab==='suppliers'?<><td><b>{r.name}</b></td><td>{r.deliveries}</td><td className="strong-cell">{num(r.units)}</td><td>{fmt(r.lastReceived)}</td></>:tab==='picking'?<><td className="mono">{r.reference}</td><td>{r.product?.name}</td><td>{r.bin?.code}</td><td><Priority value={r.priority}/></td><td><Status value={r.status}/></td></>:tab==='cycleCounts'?<><td className="mono">{r.reference}</td><td>{r.product?.name}</td><td>{r.bin?.code}</td><td>{num(r.expected)}</td><td>{r.counted===undefined?'—':num(r.counted)}</td><td>{r.counted===undefined?'—':`${r.variance>0?'+':''}${num(r.variance)}`}</td><td><Status value={r.status}/></td></>:tab==='dispatch'?<><td className="mono">{r.orderNumber}</td><td>{r.customer}</td><td>{r.product?.name}</td><td>{num(r.quantity)}</td><td><Status value={r.status}/></td></>:<><td>{fmt(r.date)}</td><td><span className={`status-pill ${r.direction==='Inbound'?'status-completed':'status-processing'}`}>{r.direction}</span></td><td className="mono">{r.reference}</td><td>{r.product?.name}</td><td>{r.party}</td><td className="strong-cell">{num(r.quantity)}</td></>}</tr>)}{!rows.length&&<tr><td colSpan="6"><EmptyRows text="No records for this report" hint="Try a wider date range or add operational records."/></td></tr>}</tbody></table></div></div></>;
}
function UsersView({token,user}){const [users,setUsers]=useState([]),[error,setError]=useState('');useEffect(()=>{api('/users',{token}).then(setUsers).catch(e=>setError(e.message))},[token]);const change=async(id,role)=>{try{const u=await api(`/users/${id}/role`,{token,method:'PATCH',body:{role}});setUsers(users.map(x=>x._id===id?u:x))}catch(e){setError(e.message)}};return <><PageHeader eyebrow="ACCESS CONTROL" title="Team access" description="Manage who can access administrative controls in your workspace."/><div className="panel data-panel">{error&&<div className="alert-banner">{error}</div>}<div className="table-wrap"><table><thead><tr><th>Team member</th><th>Email</th><th>Role</th><th>Joined</th></tr></thead><tbody>{users.map(u=><tr key={u._id}><td><span className="product-cell"><span className="avatar">{initials(u.name)}</span><b>{u.name}</b></span></td><td>{u.email}</td><td>{u._id===user.id?<span className="role-pill">{u.role}</span>:<select className="inline-select" value={u.role} onChange={e=>change(u._id,e.target.value)}><option value="staff">Staff</option><option value="admin">Administrator</option></select>}</td><td>{fmt(u.createdAt)}</td></tr>)}</tbody></table></div></div></>}
function MiniStat({label,value,color}){return <div className="mini-stat"><span>{label}</span><b className={color?`text-${color}`:''}>{value}</b></div>}

function Modal({title,children,onClose}){useEffect(()=>{const h=e=>e.key==='Escape'&&onClose();window.addEventListener('keydown',h);return()=>window.removeEventListener('keydown',h)},[onClose]);return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className="modal"><div className="modal-head"><div><div className="eyebrow">WORKSPACE</div><h2>{title}</h2></div><button className="icon-btn" onClick={onClose}><X size={18}/></button></div>{children}</div></div>}
function RecordForm({type,token,onSubmit,onError}){const [form,setForm]=useState({}),[options,setOptions]=useState({products:[],warehouses:[],bins:[]}),[busy,setBusy]=useState(false);useEffect(()=>{Promise.all([api('/products',{token}),api('/warehouses',{token}),api('/bins',{token})]).then(([products,warehouses,bins])=>setOptions({products,warehouses,bins})).catch(()=>{})},[token]);const change=e=>setForm({...form,[e.target.name]:e.target.value});const field=(name,label,props={})=><label key={name}>{label}<input name={name} value={form[name]||''} onChange={change} {...props}/></label>;const select=(name,label,list,mapper)=><label key={name}>{label}<select name={name} value={form[name]||''} onChange={change} required><option value="">Select {label.toLowerCase()}</option>{list.map(x=><option value={x._id} key={x._id}>{mapper(x)}</option>)}</select></label>;
  const config={product:{path:'/products',success:'Product added to catalogue',fields:<>{field('code','Product code',{required:true,placeholder:'e.g. SKU-1042'})}{field('name','Product name',{required:true,placeholder:'Product name'})}{field('category','Category',{placeholder:'e.g. Components'})}{field('unit','Unit of measure',{placeholder:'units'})}{field('reorderLevel','Reorder level',{type:'number',min:0,defaultValue:0})}<label className="span-2">Description<textarea name="description" onChange={change} rows="2" placeholder="Optional product details"/></label></>},warehouse:{path:'/warehouses',success:'Warehouse created',fields:<>{field('name','Warehouse name',{required:true,placeholder:'e.g. Central Distribution'})}{field('location','Location',{placeholder:'City or site'})}{field('capacity','Total capacity (units)',{type:'number',min:0,placeholder:'0'})}<label>Status<select name="status" onChange={change}><option>Active</option><option>Inactive</option></select></label></>},bin:{path:'/bins',success:'Storage bin created',fields:<>{select('warehouse','Warehouse',options.warehouses,x=>x.name)}{field('code','Bin code',{required:true,placeholder:'e.g. A-01-04'})}{field('capacity','Capacity (units)',{type:'number',min:0,placeholder:'0'})}<label>Status<select name="status" onChange={change}><option>Active</option><option>Inactive</option></select></label></>},receiving:{path:'/receiving',success:'Stock received and inventory updated',fields:<>{select('product','Product',options.products,x=>`${x.name} · ${x.code}`)}{select('bin','Destination bin',options.bins.filter(x=>x.status==='Active'),x=>`${x.code} · ${x.warehouse?.name||''}`)}{field('quantity','Quantity',{required:true,type:'number',min:1,placeholder:'0'})}{field('supplier','Supplier',{required:true,placeholder:'Supplier name'})}{field('reference','Receipt reference',{placeholder:'Auto-generated if blank'})}{field('expiryDate','Best before / expiry',{type:'date'})}</>},picking:{path:'/picking',success:'Pick task created',fields:<>{select('product','Product',options.products,x=>`${x.name} · ${x.code}`)}{select('bin','Pick from bin',options.bins,x=>`${x.code} · ${x.warehouse?.name||''}`)}{field('quantity','Quantity',{required:true,type:'number',min:1,placeholder:'0'})}<label>Priority<select name="priority" onChange={change}><option>Normal</option><option>Low</option><option>High</option><option>Urgent</option></select></label></>},dispatch:{path:'/dispatch',success:'Dispatch order created',fields:<>{field('orderNumber','Order number',{required:true,placeholder:'e.g. ORD-2048'})}{field('customer','Customer',{required:true,placeholder:'Customer name'})}{select('product','Product',options.products,x=>`${x.name} · ${x.code}`)}{field('quantity','Quantity',{required:true,type:'number',min:1,placeholder:'0'})}<label>Status<select name="status" onChange={change}><option>Pending</option><option>Processing</option></select></label><label>Dispatch date<input type="date" name="dispatchedAt" onChange={change}/></label></>}};
  config.cycleCount={path:'/cycle-counts',success:'Cycle count opened',fields:<>{select('product','Product',options.products,x=>`${x.name} · ${x.code}`)}{select('bin','Bin to count',options.bins.filter(x=>x.status==='Active'),x=>`${x.code} · ${x.warehouse?.name||''}`)}</>};const c=config[type];if(!c)return null;const submit=async e=>{e.preventDefault();setBusy(true);try{await onSubmit(c.path,'POST',form,c.success)}finally{setBusy(false)}};return <form className="record-form" onSubmit={submit}><div className="form-grid">{c.fields}</div><div className="modal-actions"><button type="button" className="btn btn-secondary" onClick={()=>document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape'}))}>Cancel</button><button className="btn btn-primary" disabled={busy}>{busy?'Saving…':'Save record'} <ArrowRight size={15}/></button></div></form>}

export default App;
